#[cfg(test)]
mod tests {
    #[allow(unused_imports)]
    #[allow(unused_imports)]
    use std::num::NonZeroU32;
    #[test]
    pub fn test_default() {
        assert_eq!(
            format!("{:#?}", super::IsSetLabel::get(super::LabelEmpty)),
            format!("{:#?}", wgpu_27::Label::default()),
        );
        assert_eq!(
            format!("{:#?}", super::IsSetLayout::get(super::LayoutEmpty)),
            format!("{:#?}", Option::<&wgpu_27::PipelineLayout>::default()),
        );
        assert_eq!(
            format!("{:#?}", super::IsSetTask::get(super::TaskEmpty)),
            format!("{:#?}", Option::<wgpu_27::TaskState>::default()),
        );
        assert_eq!(
            format!("{:#?}", super::IsSetPrimitive::get(super::PrimitiveEmpty)),
            format!("{:#?}", wgpu_27::PrimitiveState::default()),
        );
        assert_eq!(
            format!(
                "{:#?}",
                super::IsSetDepthStencil::get(super::DepthStencilEmpty)
            ),
            format!("{:#?}", Option::<wgpu_27::DepthStencilState>::default()),
        );
        assert_eq!(
            format!(
                "{:#?}",
                super::IsSetMultisample::get(super::MultisampleEmpty)
            ),
            format!("{:#?}", wgpu_27::MultisampleState::default()),
        );
        assert_eq!(
            format!("{:#?}", super::IsSetFragment::get(super::FragmentEmpty)),
            format!("{:#?}", Option::<wgpu_27::FragmentState>::default()),
        );
        assert_eq!(
            format!("{:#?}", super::IsSetMultiview::get(super::MultiviewEmpty)),
            format!("{:#?}", Option::<NonZeroU32>::default()),
        );
        assert_eq!(
            format!("{:#?}", super::IsSetCache::get(super::CacheEmpty)),
            format!("{:#?}", Option::<&wgpu_27::PipelineCache>::default()),
        );
    }
}
